WITH catalog_agg AS ( SELECT cs.cs_ship_mode_sk, SUM(cs.cs_net_paid) AS cat_total_net_paid, AVG(cs.cs_ext_discount_amt) AS cat_avg_discount, SUM(cs.cs_net_profit) AS cat_total_profit FROM catalog_sales cs GROUP BY cs.cs_ship_mode_sk ), web_agg AS ( SELECT ws.ws_ship_mode_sk, SUM(ws.ws_net_paid) AS web_total_net_paid, AVG(ws.ws_ext_discount_amt) AS web_avg_discount, SUM(ws.ws_net_profit) AS web_total_profit FROM web_sales ws GROUP BY ws.ws_ship_mode_sk ) SELECT sm.sm_ship_mode_id, sm.sm_type, COALESCE(ca.cat_total_net_paid, 0) AS catalog_net_paid, COALESCE(wa.web_total_net_paid, 0) AS web_net_paid, COALESCE(ca.cat_total_net_paid, 0) + COALESCE(wa.web_total_net_paid, 0) AS combined_net_paid, COALESCE(ca.cat_avg_discount, 0) AS catalog_avg_discount, COALESCE(wa.web_avg_discount, 0) AS web_avg_discount, CASE WHEN sm.sm_type = 'Air' THEN 'Fast' WHEN sm.sm_type = 'Ground' THEN 'Standard' ELSE 'Other' END AS shipping_category, DENSE_RANK() OVER (ORDER BY COALESCE(ca.cat_total_net_paid, 0) + COALESCE(wa.web_total_net_paid, 0) DESC) AS net_paid_rank FROM ship_mode sm LEFT JOIN catalog_agg ca ON sm.sm_ship_mode_sk = ca.cs_ship_mode_sk LEFT JOIN web_agg wa ON sm.sm_ship_mode_sk = wa.ws_ship_mode_sk ORDER BY net_paid_rank LIMIT 10
